/// The pattern predicates still checked when a function is selected.
pub fn pattern_predicate<C: PatternContext>(ctx: &C, id: u16) -> bool {
    match id {
        1 => ctx.neon_available(),
        9 => (ctx.has_feature("FullFP16")) && (ctx.neon_available()),
        10 => ctx.has_feature("FullFP16"),
        11 => ctx.neon_available(),
        12 => ctx.has_feature("LSE"),
        24 => (ctx.has_feature("FullFP16")) && (ctx.neon_available()),
        29 => ctx.has_feature("SHA3"),
        41 => (ctx.neon_available()) && (ctx.has_feature("RDM")),
        72 => ctx.has_feature("SHA2"),
        74 => ctx.has_feature("AES"),
        82 => ctx.has_feature("CRC"),
        94 => ctx.has_feature("RCPC"),
        99 => ctx.has_feature("RDM"),
        108 => !ctx.has_feature("LSE"),
        _ => unreachable!("pattern predicate {id} is not in this table"),
    }
}

/// The node predicates the table checks.
